UPDATE lessons SET title='Year 3, Week 4, Lesson 2: Show, don''t tell', data=json_patch(data,'{"child_mission":"Show feelings through actions and details instead of naming the emotion directly.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Keep the independent response and two written check responses; record oral retelling or performance where required by the task.","explicit_teaching":null,"extension":"Create a new example using a completely different character or setting, show the same skill, then explain to another person how you checked its accuracy.","follow_up_challenges":null,"guided_practice":"WE DO — attempt each prompt before comparing to the feedback.\n1. Rewrite \"Tom was angry\" using actions only.\nCOMPARE: Example: \"Tom slammed his pencil onto the desk and stared at the torn page.\" The actions imply anger.\n2. Write two clues that could show worry at a bus stop.\nCOMPARE: Checking the timetable twice and biting a lip are useful clues; naming the bus colour is not.\n3. Trim a draft that lists five adjectives for surprise into two clear sentences.\nCOMPARE: Choose two concrete actions; delete repeated describing words that do not add evidence.\n4. Improve a scene that could mean either surprise or fear.\nCOMPARE: Add a clue that distinguishes them, such as a jump back for fear versus a wide grin for pleasant surprise.","hoard_words":null,"independent_task":"YOU DO — complete the following substantial original task, not a copied model.\nWrite three short original scenes (two sentences each) that show worry, surprise and relief without using those three words. Underline the exact actions that suggest each feeling and explain one choice.","interactive_activities":null,"learning_area":"English","learning_intention":"Show feelings through actions and details instead of naming the emotion directly.","lesson_number":2,"lesson_role":"Writing","materials":["Paper or typing area","Pencil for optional evidence"],"offline_alternative":"Use paper to copy only the original independent prompt; have the child respond in writing or orally as required. Save a photograph or brief parent observation for the learning record.","outcome_codes":["EN2-CWT-01"],"parent_notes":"Parent: Marking guidance for the independent task: Write three short original scenes (two sentences each) that show worry, surprise and relief without using those three words. Underline the exact actions that suggest each feeling and explain one choice. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: original example using showing on new material; names a specific word, source or choice and explains its effect.\n\nParent: Written model 2: Sample error: Replacing angry with mad still tells;. Correction: Example: \"Tom slammed his pencil onto the desk and stared at the torn page.\" The actions imply anger.. Why it helps the audience is stated.\n\nParent: Likely misconception: Replacing angry with mad still tells; show observable evidence. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating showing on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with showing, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Accept original work about showing with a specific supporting detail. Reject copied model wording with no new material. / Accept a misconception, a correction, and a purpose-linked reason for showing. Reject corrections that do not change the inaccurate idea..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"This matches the taught method for showing. The other choices miss a key step or use a common mistake.","options":["Example: \"Tom slammed his pencil onto the desk and stared at the torn page.\" The actions imply anger.","Replacing angry with mad still tells;","A claim that names no evidence from the lesson material.","A method that skips the key step taught in this lesson."],"question":"Write two clues that could show worry at a bus stop. Which response is most accurate?","type":"multiple_choice"},{"correct_index":3,"explanation":"This is the misconception to avoid for showing; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Show feelings through actions and details instead of naming the emotion directly.","Example: \"Tom slammed his pencil onto the desk and stared at the torn page.\" The actions imply anger.","Careful use of telling and point to the words or events with clear evidence.","Replacing angry with mad still tells;"],"question":"Which statement is a common mistake when working with showing?","type":"multiple_choice"},{"correct_index":1,"explanation":"Understanding is shown by new evidence and a named telling and point to the words or events, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Name telling and point to the words or events only, without linking it to showing.","Apply showing to new material and name the telling and point to the words or events used.","Repeat the worked example wording with no new evidence.","Replacing angry with mad still tells;"],"question":"Which response best applies showing with new evidence?","type":"multiple_choice"},{"correct_index":3,"explanation":"The skill is shown by quoting or pointing to wording that carries showing. The other choices miss a key step or use a common mistake.","options":["Ignore the sentence and invent a more exciting event.","Say the writing is good without naming any words.","Replacing angry with mad still tells;","Point to exact words in the sentence that show showing and say what they do."],"question":"Read: \"In the dusty shed, Lila oiled the bike chain before the race.\" Which choice best uses showing from this lesson?","type":"multiple_choice"},{"correct_index":3,"explanation":"The correct statement applies the language skill with textual evidence. The other choices miss a key step or use a common mistake.","options":["Replacing angry with mad still tells;","Copy a model sentence from another story unchanged.","Name telling and point to the words or events without linking it to any words in the text.","Example: \"Tom slammed his pencil onto the desk and stared at the torn page.\" The actions imply anger."],"question":"Which statement correctly applies the lesson idea about showing?","type":"multiple_choice"},{"correct_index":1,"explanation":"Start from a specific textual clue, then explain its effect. The other choices miss a key step or use a common mistake.","options":["Lengthen the answer with adjectives while keeping the same idea.","Locate a specific word, phrase or structural clue before deciding.","Guess from the title alone with no textual clue.","Copy a model sentence from another story unchanged."],"question":"In a new text, what should you do first to analyse telling and point to the words or events?","type":"multiple_choice"},{"correct_index":0,"explanation":"Repair means fixing meaning or evidence, not padding. The other choices miss a key step or use a common mistake.","options":["Change the inaccurate idea or missing evidence, not only the length.","Add adjectives without fixing the wrong idea.","Make the answer longer while keeping the same mistake.","Delete the evidence that disagreed with your first guess."],"question":"Which revision actually improves meaning for showing?","type":"multiple_choice"},{"correct_index":1,"explanation":"Accurate transfer needs fresh material with an explained language choice. The other choices miss a key step or use a common mistake.","options":["Replacing angry with mad still tells;","Use a fresh sentence or text and explain one precise choice about showing.","Retype the worked model as the final answer.","Change fonts and claim the work is new."],"question":"Which response shows accurate use of showing on fresh material?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept original work about showing with a specific supporting detail. Reject copied model wording with no new material.","question":"Produce a fresh example demonstrating showing on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Sample: original example using showing on new material; names a specific word, source or choice and explains its effect.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception, a correction, and a purpose-linked reason for showing. Reject corrections that do not change the inaccurate idea.","question":"Name one likely error with showing, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Sample error: Replacing angry with mad still tells;. Correction: Example: \"Tom slammed his pencil onto the desk and stared at the torn page.\" The actions imply anger.. Why it helps the audience is stated.","type":"short_answer"}],"resources":null,"response_prompt":"Submit your original independent work and your brief explanation of the key choices you made.","review_status":"unreviewed","seed_key":"s2-eng-y3-w04-l2","sort_activity":null,"source_note":"Proposed Stage 2 NESA alignment; compare the existing Coming Soon card and official syllabus content points before marking verified.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise showing.","Read the mission before you start writing or speaking.","Your goal is: Show feelings through actions and details instead of naming the emotion directly."],"guided":["Attempt each guided prompt without looking ahead.","Compare your attempt with the supplied specific feedback.","Guided comparison: Checking the timetable twice and biting a lip are useful clues; naming the bus colour is not."],"learn":["Study the first worked demonstration carefully.","Name the exact words or events that make it work.","Demonstration: \"Pia was frightened\" tells. \"Pia gripped the railing as the floorboards creaked\" shows clues that suggest fear without using that word."],"quiz":["Read the whole question and eliminate misconceptions.","Prefer the option that quotes or uses actual evidence.","Likely trap: Piling synonyms for the emotion is still telling."],"submit":["Include your own response and a short reason.","Proofread names, sequence and punctuation before sending.","Success looks like: Show feelings through actions and details instead of naming the emotion directly."],"teach0":["Focus on name the feeling, then remove the label.","Hold this teaching point: Telling names the emotion; showing lets the reader infer it from actions, body language and surroundings.","Worked comparison: Example: \"Tom slammed his pencil onto the desk and stared at the torn page.\" The actions imply anger."],"teach1":["Focus on choose useful sensory or physical clues.","Hold this teaching point: Not every detail helps. Choose actions a reader can picture that point towards one feeling.","Worked comparison: Checking the timetable twice and biting a lip are useful clues; naming the bus colour is not."],"teach2":["Focus on keep the scene short and clear.","Hold this teaching point: Two or three precise sentences are stronger than a long list of adjectives.","Worked comparison: Choose two concrete actions; delete repeated describing words that do not add evidence."],"teach3":["Focus on check a reader can infer the intended feeling.","Hold this teaching point: Read your scene aloud and ask what feeling seems most likely. If several feelings fit equally, add one clearer clue.","Worked comparison: Add a clue that distinguishes them, such as a jump back for fear versus a wide grin for pleasant surprise."],"write":["Use the independent instructions, not the model words.","Give an original response and the reason behind it.","Independent reminder: Write three short original scenes (two sentences each) that show worry, surprise and relief without using those three words. Underline the exact actions that su"]},"subject":"English","success_criteria":["I can use showing with a specific example from this lesson.","I can identify telling and point to the words or events that support it.","I can practise clue independently on a new prompt.","I can notice inference needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Use the example and explain the clue or language choice before trying showing independently.","Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail."],"question":"Which choice best applies this lesson idea about showing with clear evidence?","type":"multiple_choice"},"example":"WATCH MY THINKING\n\"Pia was frightened\" tells. \"Pia gripped the railing as the floorboards creaked\" shows clues that suggest fear without using that word.\n\nYOUR SMALL TRY\nRewrite \"Tom was angry\" using actions only.\n\nCOMPARE AND CORRECT\nExample: \"Tom slammed his pencil onto the desk and stared at the torn page.\" The actions imply anger.","explain":"Telling names the emotion; showing lets the reader infer it from actions, body language and surroundings.\n\nTelling names the emotion; showing lets the reader infer it from actions, body language and surroundings. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nReplacing angry with mad still tells; show observable evidence. Re-read the prompt and correct the misunderstanding before moving on.","title":"Name the feeling, then remove the label","visual":[{"alt":"Telling names fear while showing uses gripping the railing as evidence.","caption":"Show observable actions so a reader can infer the feeling.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Tells</text><text x=\"28\" y=\"78\">Pia was frightened</text><text x=\"358\" y=\"42\">Shows</text><text x=\"358\" y=\"78\">Pia gripped the railing</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I read the first example, but I am not sure which detail matters most.","who":"pip"},{"text":"Name the exact words or events that carry the meaning before you copy a conclusion.","who":"juno"},{"text":"So I should try the small prompt myself, then compare it with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: \"Pia was frightened\" tells. \"Pia gripped the railing as the floorboards creaked\" shows clues that suggest fear without u Then write your own attempt.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I read the first example, but I am not sure which detail matters most.\nJuno: Name the exact words or events that carry the meaning before you copy a conclusion.\nPip: So I should try the small prompt myself, then compare it with the feedback.\nJuno: Pause here. Use this model: \"Pia was frightened\" tells. \"Pia gripped the railing as the floorboards creaked\" shows clues that suggest fear without u Then write your own attempt."}}]},{"check":{"correct_index":1,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Add a made-up event and describe it as a fact.","Use the example and explain the clue or language choice before trying telling independently.","Ignore the task and choose an unrelated detail.","Copy every sentence exactly without explaining it."],"question":"Which choice best applies this lesson idea about showing with clear evidence?","type":"multiple_choice"},"example":"WATCH MY THINKING\nFor excitement I write \"Amira bounced on her toes and checked the window again.\" The bouncing and repeated checking suggest anticipation.\n\nYOUR SMALL TRY\nWrite two clues that could show worry at a bus stop.\n\nCOMPARE AND CORRECT\nChecking the timetable twice and biting a lip are useful clues; naming the bus colour is not.","explain":"Not every detail helps. Choose actions a reader can picture that point towards one feeling.\n\nNot every detail helps. Choose actions a reader can picture that point towards one feeling. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nA smile alone can mean many feelings; add a second confirming clue. Re-read the prompt and correct the misunderstanding before moving on.","title":"Choose useful sensory or physical clues","visual":[{"alt":"A smile alone versus bouncing and checking a window as excitement clues.","caption":"One ambiguous clue is weaker than two confirming actions.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Weak clue</text><text x=\"28\" y=\"78\">smiled only</text><text x=\"358\" y=\"42\">Stronger clues</text><text x=\"358\" y=\"78\">bounced and checked the window</text></g></svg>"}]},{"check":{"correct_index":3,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail.","Use the example and explain the clue or language choice before trying clue independently."],"question":"Which choice best applies this lesson idea about showing with clear evidence?","type":"multiple_choice"},"example":"WATCH MY THINKING\n\"Leo''s hands shook as he opened the envelope. He exhaled when he saw his name.\" Relief is clear without naming it.\n\nYOUR SMALL TRY\nTrim a draft that lists five adjectives for surprise into two clear sentences.\n\nCOMPARE AND CORRECT\nChoose two concrete actions; delete repeated describing words that do not add evidence.","explain":"Two or three precise sentences are stronger than a long list of adjectives.\n\nTwo or three precise sentences are stronger than a long list of adjectives. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nPiling synonyms for the emotion is still telling. Re-read the prompt and correct the misunderstanding before moving on.","title":"Keep the scene short and clear"},{"check":{"correct_index":3,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail.","Use the example and explain the clue or language choice before trying inference independently."],"question":"Which choice best applies this lesson idea about showing with clear evidence?","type":"multiple_choice"},"example":"WATCH MY THINKING\nMy draft about a lost dog could sound sad or calm. I add \"He wiped his eyes on his sleeve\" so sadness is clearer.\n\nYOUR SMALL TRY\nImprove a scene that could mean either surprise or fear.\n\nCOMPARE AND CORRECT\nAdd a clue that distinguishes them, such as a jump back for fear versus a wide grin for pleasant surprise.","explain":"Read your scene aloud and ask what feeling seems most likely. If several feelings fit equally, add one clearer clue.\n\nRead your scene aloud and ask what feeling seems most likely. If several feelings fit equally, add one clearer clue. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nDo not claim the feeling is obvious if your clues support more than one reading. Re-read the prompt and correct the misunderstanding before moving on.","title":"Check a reader can infer the intended feeling"}],"title":"Year 3, Week 4, Lesson 2: Show, don''t tell","unit_number":1,"unit_title":"Narrative: story elements and planning","week":4,"week_in_unit":4,"word_challenges":null,"worked_example":"I DO — \"Pia was frightened\" tells. \"Pia gripped the railing as the floorboards creaked\" shows clues that suggest fear without using that word.\n\nNow look for the exact evidence in the words or actions. For excitement I write \"Amira bounced on her toes and checked the window again.\" The bouncing and repeated checking suggest anticipation.","worked_visuals":[{"alt":"Telling names fear while showing uses gripping the railing as evidence.","caption":"Show observable actions so a reader can infer the feeling.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Tells</text><text x=\"28\" y=\"78\">Pia was frightened</text><text x=\"358\" y=\"42\">Shows</text><text x=\"358\" y=\"78\">Pia gripped the railing</text></g></svg>"},{"alt":"A smile alone versus bouncing and checking a window as excitement clues.","caption":"One ambiguous clue is weaker than two confirming actions.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Weak clue</text><text x=\"28\" y=\"78\">smiled only</text><text x=\"358\" y=\"42\">Stronger clues</text><text x=\"358\" y=\"78\">bounced and checked the window</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-eng-y3-w04-l2' AND family_id IS NULL;
